1	/**
2	 * VR-1: `nexus verify`, the verdict on a change that Nexus did not necessarily make: a working tree against a commit,
3	 * or one commit against another. No model is involved.
4	 *
5	 * Both sides are materialised into scratch directories (the caller's checkout is never written), the verifier is taken
6	 * from the operator or discovered in the BASE tree (the head is the change under test and cannot choose its own judge),
7	 * it is run on the base and on the head, and the outcome is derived by the same rules the agent applies to its own
8	 * work: this module re-composes captureChangeBaselineImpl / judgeIndependenceImpl (core/completion_oracle.ts) and the
9	 * evidence built in core/spine_handlers.ts, and derives the outcome with outcomeFromEvidence. The project type-checks
10	 * run on both sides as the agent's oracle runs them (core/typecheck_evidence.ts), and every changed file that defines
11	 * or weakens the verification is a guard finding, classified under the BASE tree's policy.
12	 *
13	 * Where each thing is read: the guard reads both trees before any repository code has run in them; the verifier runs in
14	 * `base` and `head`; the type-checks run in copies of their own (`base-typecheck`, `head-typecheck`), because a checker
15	 * may write build output; and the head is judged on `head-pristine`, a copy nothing has run in.
16	 *
17	 * Authority: the request names only what to compare. Everything that can raise the verdict (the verifier command, its
18	 * approval, the declared deliverables, the deadline) comes from the operator context. Anything that cannot be fully
19	 * evaluated lowers the verdict with a reason that names it; nothing here raises one.
20	 */
21	import fs from "node:fs";
22	import os from "node:os";
23	import path from "node:path";
24	import { createHash } from "node:crypto";
25	import { getBuildIdentity } from "../build_identity.js";
26	import { trustedGitArgs } from "../git.js";
27	import { SecurityManager, conditionalConfigChanged, isConditionalConfig, neutersTests } from "../security.js";
28	import {
29	  MAX_TEST_BYTES, SKIP_DIRS, describeVerifier, discoverTypechecks, discoverVerifier, hasExecutedTests, isFilteredVerifierCommand, isVerifierDeliverableBound,
30	  runVerifierShell, typecheckMode, verifierTimeoutSecs, type DiscoveredTypecheck, type TimedExecutor,
31	} from "../tester.js";
32	import { formatDiagnosticForOutput, safeTerminal } from "../ui.js";
33	import {
34	  VERIFY_RESULT_SCHEMA_VERSION, verifyExitCode, verifyExitNameFor, verifyVerdictFor,
35	  type VerifyGuard, type VerifyGuardFinding, type VerifyJsonResult, type VerifyReason, type VerifyRunRecord, type VerifyTreeRef, type VerifyVerifierRecord,
36	} from "../verify_contract.js";
37	import { GitError, UntrustedCheckoutError, git, printable } from "../worktrunk/git.js";
38	import {
39	  isInlineProgramVerifier, judgeWithoutCopy, prepareBaselineTestsCopy, requiresWorkspaceVerifierDefinitionBinding, snapshotTests,
40	  snapshotVerifierDefinitionWithReason, testsChangedSince, verifierDefinitionChangedSince, type ChangeBaseline, type Independence,
41	} from "./independent_check.js";
42	import { classifyTestEdit } from "./regression_obligations.js";
43	import type { TypecheckEvidence, VerificationEvidence } from "./turn.js";
44	import { captureTypecheckBaseline, collectTypecheckEvidence, typecheckNotApplicable, typecheckProjectKey, worstTypecheckBlock } from "./typecheck_evidence.js";
45	import { outcomeFromEvidence } from "./verification_outcome.js";
46	
47	/** What to compare. Nothing here can raise the verdict, so this is the part a remote caller may supply. */
48	export interface VerifyRequest {
49	  /** The top of a Git working tree. */
50	  worktree: string;
51	  /** The commit the change starts from (default `HEAD`). */
52	  base?: string;
53	  /** The commit that holds the change; absent to verify the working tree. */
54	  head?: string;
55	}
56	
57	/** What only the operator (the launcher's command line) decides. */
58	export interface VerifyOperatorContext {
59	  /** The operator's own verifier command; absent to discover one in the base tree. */
60	  verifierCommand?: string;
61	  /** Approve whatever verifier is discovered (`--yes`). */
62	  approveDiscoveredVerifier?: boolean;
63	  /** Approve the discovered verifier with exactly this digest (`--approve-verifier`). */
64	  approvedVerifierDigest?: string;
65	  /** Workspace-relative product files the change is meant to deliver. */
66	  deliverables?: readonly string[];
67	  /** Workspace-relative verification files whose edit the operator approves (`--approve-verification-edit`). */
68	  approvedVerificationEdits?: readonly string[];
69	  /** Deadline of each verifier run, and of each side's type-checks, in seconds (default: NEXUS_VERIFIER_TIMEOUT_SECS, else 300). */
70	  timeoutSecs?: number;
71	  /** Aborted to interrupt: acted on between child processes. */
72	  signal?: AbortSignal;
73	  /** Progress lines for a person (never part of the result). */
74	  onProgress?: (message: string) => void;
75	}
76	
77	/** The request or the options cannot be acted on: not a working tree, a ref that names no commit, a bad path. */
78	export class VerifyUsageError extends Error {
79	  constructor(message: string) {
80	    super(message);
81	    this.name = "VerifyUsageError";
82	  }
83	}
84	
85	export class VerifyInterrupted extends Error {
86	  constructor() {
87	    super("interrupted");
88	    this.name = "VerifyInterrupted";
89	  }
90	}
91	
92	/** Largest tree materialised: files and total bytes. A larger tree is BLOCKED, never verified in part. */
93	export const VERIFY_MAX_TREE_FILES = 20_000;
94	export const VERIFY_MAX_TREE_BYTES = 512 * 1024 * 1024;
95	/** Deadline of each Git command that reads or writes a whole tree, and of each small one. */
96	const GIT_TREE_TIMEOUT_MS = 120_000;
97	const GIT_TIMEOUT_MS = 30_000;
98	const GIT_LISTING_BUFFER = 64 * 1024 * 1024;
99	/** Dependency directories of the caller's checkout linked into the scratch trees, so both sides run with the same installed packages. */
100	const DEPENDENCY_DIRS: readonly string[] = ["node_modules", "vendor", ".venv", "venv"];
101	const MAX_DEPENDENCY_LINKS = 64;
102	const MAX_DEPENDENCY_SCAN = 2000;
103	const MAX_LISTED_CHANGES = 200;
104	/** Most guard findings one result lists. A change with more is BLOCKED as incompletely classified, never listed in part as if whole. */
105	export const VERIFY_MAX_GUARD_FINDINGS = 1000;
106	/** Largest verification file whose text the guard reads to classify an edit. */
107	export const VERIFY_MAX_GUARD_FILE_BYTES = MAX_TEST_BYTES;
108	/** Reasons that say the head was run and did not pass. They outrank a guard finding: "it fails" is reported before "a person must decide". */
109	const HEAD_RUN_FAILURES: readonly VerifyReason[] = ["VERIFIER_FAILED", "VERIFIER_TIMED_OUT", "TYPECHECK_FAILED", "TYPECHECK_TIMED_OUT", "TYPECHECK_UNAVAILABLE"];
110	const WORKING_TREE = "(working tree)";
111	/** Variables that can change the verdict or what the verifier sees: their NAMES are recorded when set. */
112	export const VERIFY_RECORDED_ENVIRONMENT: readonly string[] = ["NEXUS_TRUST_WORKSPACE", "NEXUS_TYPECHECK", "NEXUS_VERIFIER_TIMEOUT_SECS", "NEXUS_VERIFIER_ENV_PASSTHROUGH"];
113	
114	/** Ends verification early with a verdict that is not VERIFIED. */
115	class Stop extends Error {
116	  constructor(readonly reason: VerifyReason, readonly detail: string) {
117	    super(detail);
118	  }
119	}
120	
121	// Scratch directories still on disk. Removed in verifyChange's `finally`; the exit hook covers a process.exit() in between.
122	const liveScratch = new Set<string>();
123	let exitHook = false;
124	function removeScratch(dir: string): void {
125	  try { fs.rmSync(dir, { recursive: true, force: true }); } catch { /* reported by the caller's leak, not fatal here */ }
126	  liveScratch.delete(dir);
127	}
128	function makeScratch(): string {
129	  if (!exitHook) {
130	    exitHook = true;
131	    process.on("exit", () => { for (const dir of [...liveScratch]) removeScratch(dir); });
132	  }
133	  // Resolved: the snapshot functions compare real paths with the workspace root, and a temp directory can sit behind a link.
134	  const dir = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "nexus-verify-")));
135	  liveScratch.add(dir);
136	  return dir;
137	}
138	
139	const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");
140	const capped = (text: string, max: number) => (text.length > max ? `${text.slice(0, max)}…` : text);
141	
142	function validRef(ref: string): boolean {
143	  return ref.length > 0 && ref.length <= 256 && !ref.startsWith("-") && !/[\0\r\n]/.test(ref);
144	}
145	
146	/** An operator-named file as a normalised workspace-relative path; a path that is absolute or leaves the tree is refused. */
147	function normaliseTreePath(option: string, file: string): string {
148	  const normal = path.posix.normalize(file.trim().replace(/\\/g, "/")).replace(/^\.\//, "");
149	  if (!normal || normal === "." || normal.startsWith("../") || normal === ".." || path.isAbsolute(normal) || /[\0\r\n]/.test(normal)) {
150	    throw new VerifyUsageError(`${option} ${printable(file)} is not a path inside the working tree`);
151	  }
152	  return normal;
153	}
154	
155	/**
156	 * The verification-file guard: every changed file that decides how the change is verified, and for a test file what
157	 * the edit took away. Call it before any repository code has run in `baseDir` or `headDir`.
158	 *
159	 * The policy (mode, extra paths) is the BASE tree's `.nexus-security.json`, read as an UNTRUSTED repository's: it can
160	 * tighten the guard (mode `block`, more paths) and never relax it. The head's policy file is never read as policy; it
161	 * is itself a finding. NEXUS_TRUST_WORKSPACE is deliberately not honoured: the operator's trust in a checkout is not
162	 * trust in the commit under review, so the variable is taken out of the environment while the policy is loaded.
163	 */
164	function classifyVerificationEdits(baseDir: string, headDir: string, changed: readonly string[], approved: ReadonlySet<string>): VerifyGuard {
165	  const trustOverride = process.env.NEXUS_TRUST_WORKSPACE;
166	  delete process.env.NEXUS_TRUST_WORKSPACE;
167	  let manager: SecurityManager;
168	  try {
169	    manager = new SecurityManager(baseDir);
170	  } finally {
171	    if (trustOverride !== undefined) process.env.NEXUS_TRUST_WORKSPACE = trustOverride;
172	  }
173	  const mode = manager.getPolicy().verificationPaths?.mode ?? "approve";
174	  const present = (directory: string, rel: string) => {
175	    try { fs.lstatSync(path.join(directory, rel)); return true; } catch { return false; }
176	  };
177	  /** The file's text; null when it is absent; undefined when it cannot be read as a small regular file. */
178	  const read = (directory: string, rel: string): string | null | undefined => {
179	    const file = path.join(directory, rel);
180	    let stat: fs.Stats;
181	    try { stat = fs.lstatSync(file); } catch { return null; }
182	    if (!stat.isFile() || stat.size > VERIFY_MAX_GUARD_FILE_BYTES) return undefined;
183	    try { return fs.readFileSync(file, "utf8"); } catch { return undefined; }
184	  };
185	  const findings: VerifyGuardFinding[] = [];
186	  const unclassified: string[] = [];
187	  for (const rel of changed) {
188	    const found = manager.classifyVerificationPath(rel);
189	    if (!found) continue;
190	    const inBase = present(baseDir, rel);
191	    const inHead = present(headDir, rel);
192	    const kind: VerifyGuardFinding["kind"] = !inBase ? "added" : !inHead ? "deleted" : "modified";
193	    let weakening: string[] | undefined;
194	    let requiresApproval = found.class !== "test_file";
195	    if (found.class === "test_file") {
196	      // A new test file is free, as it is for the agent's file tools (security.ts verificationEditDecision).
197	      if (kind === "deleted") weakening = ["removed"];
198	      else if (kind === "modified") {
199	        const before = read(baseDir, rel);
200	        const after = read(headDir, rel);
201	        if (typeof before !== "string" || typeof after !== "string") {
202	          unclassified.push(rel);
203	          weakening = ["unverifiable-change"];
204	        } else {
205	          const kinds: string[] = classifyTestEdit(before, after).map((signal) => signal.kind);
206	          const was = new Set(before.split("\n"));
207	          if (!kinds.includes("skipped") && neutersTests(after.split("\n").filter((line) => !was.has(line)).join("\n"))) kinds.push("neutered");
208	          if (kinds.length) weakening = kinds;
209	        }
210	      }
211	      requiresApproval = weakening !== undefined;
212	    } else if (isConditionalConfig(rel) && kind !== "deleted") {
213	      // package.json, pyproject.toml, setup.cfg: only the keys or sections that decide how tests run are verification configuration.
214	      const before = read(baseDir, rel);
215	      const after = read(headDir, rel);
216	      if (before === undefined || typeof after !== "string") unclassified.push(rel);
217	      else {
218	        let touches = true;
219	        try { touches = conditionalConfigChanged(rel, before, after); } catch { /* not parseable: treated as a verification edit */ }
220	        if (!touches) continue;
221	      }
222	    }
223	    if (findings.length >= VERIFY_MAX_GUARD_FINDINGS) {
224	      return {
225	        status: "BLOCKED", mode, policySource: present(baseDir, ".nexus-security.json") ? "base_tree" : "default", findings, complete: false,
226	        detail: `the change touches more than ${VERIFY_MAX_GUARD_FINDINGS} verification files; the findings listed are not all of them`,
227	      };
228	    }
229	    findings.push({ path: printable(rel), class: found.class, kind, ...(weakening ? { weakening } : {}), requiresApproval, approved: requiresApproval && approved.has(rel) });
230	  }
231	  const complete = unclassified.length === 0;
232	  const enforced = mode === "approve" || mode === "block";
233	  const waiting = enforced && findings.some((finding) => finding.requiresApproval && (mode === "block" || !finding.approved));
234	  return {
235	    status: !complete || waiting ? "BLOCKED" : "CLEAR",
236	    mode,
237	    policySource: present(baseDir, ".nexus-security.json") ? "base_tree" : "default",
238	    findings,
239	    complete,
240	    ...(complete ? {} : { detail: `could not be read to classify the edit (not a regular file, or larger than ${VERIFY_MAX_GUARD_FILE_BYTES} bytes): ${unclassified.slice(0, 5).map((rel) => printable(rel)).join(", ")}${unclassified.length > 5 ? ` and ${unclassified.length - 5} more` : ""}` }),
241	  };
242	}
243	
244	const describeFinding = (finding: VerifyGuardFinding) => `${finding.path} (${finding.class}, ${finding.kind}${finding.weakening ? `: ${finding.weakening.join(", ")}` : ""})`;
245	
246	/** Cargo's type-check builds into a directory of its own under the temp directory, named in its command (tester.ts). Removed here, since the tree it belongs to is a scratch copy. */
247	function removeTypecheckBuildOutput(checks: readonly DiscoveredTypecheck[]): void {
248	  for (const check of checks) {
249	    const target = check.tool === "cargo" ? check.command.match(/^CARGO_TARGET_DIR='([^']+)' /)?.[1] : undefined;
250	    if (target && path.dirname(target) === os.tmpdir() && /^nexus-typecheck-[0-9a-f]{16}$/.test(path.basename(target))) fs.rmSync(target, { recursive: true, force: true });
251	  }
252	}
253	
254	/** Whether `relative` below `root` is reached through real directories only (no link on the way). */
255	function realDirectoryInside(root: string, relative: string): boolean {
256	  let cursor = root;
257	  for (const part of relative.split(path.sep).filter(Boolean)) {
258	    cursor = path.join(cursor, part);
259	    try {
260	      if (!fs.lstatSync(cursor).isDirectory()) return false;
261	    } catch {
262	      return false;
263	    }
264	  }
265	  return true;
266	}
267	
268	/**
269	 * Links the caller's dependency directories (those the trees do not hold themselves) into every scratch tree, so base
270	 * and head run with the same installed packages. Bounded; links in the caller's checkout are not followed.
271	 */
272	function linkDependencyDirs(worktree: string, targets: readonly string[]): string[] {
273	  const linked: string[] = [];
274	  let scanned = 0;
275	  const walk = (relative: string, depth: number) => {
276	    if (depth > 3 || linked.length >= MAX_DEPENDENCY_LINKS) return;
277	    let entries: fs.Dirent[];
278	    try { entries = fs.readdirSync(path.join(worktree, relative), { withFileTypes: true }); } catch { return; }
279	    for (const entry of entries) {
280	      if (++scanned > MAX_DEPENDENCY_SCAN || linked.length >= MAX_DEPENDENCY_LINKS) return;
281	      if (!entry.isDirectory()) continue;
282	      const child = path.join(relative, entry.name);
283	      if (DEPENDENCY_DIRS.includes(entry.name)) {
284	        let used = false;
285	        for (const target of targets) {
286	          const destination = path.join(target, child);
287	          if (!realDirectoryInside(target, relative)) continue;
288	          try { fs.lstatSync(destination); continue; } catch { /* the tree has nothing there: link it */ }
289	          fs.symlinkSync(path.join(worktree, child), destination, "dir");
290	          used = true;
291	        }
292	        if (used) linked.push(child.split(path.sep).join("/"));
293	      } else if (!SKIP_DIRS.has(entry.name)) {
294	        walk(child, depth + 1);
295	      }
296	    }
297	  };
298	  walk("", 0);
299	  return linked.sort();
300	}
301	
302	/**
303	 * The verdict on the change from `request.base` to `request.head` (or to the working tree). Returns a result for every
304	 * ending that has a verdict, including a refusal and an internal error; throws VerifyUsageError for a request that
305	 * cannot be acted on and VerifyInterrupted when the signal aborted. Scratch directories are removed on every path.
306	 */
307	export async function verifyChange(request: VerifyRequest, operator: VerifyOperatorContext = {}): Promise<VerifyJsonResult> {
308	  const started = Date.now();
309	  const timeoutSecs = verifierTimeoutSecs(operator.timeoutSecs);
310	  const deliverables = [...new Set((operator.deliverables ?? []).map((file) => normaliseTreePath("--deliverable-file", file)))];
311	  const approvedEdits = [...new Set((operator.approvedVerificationEdits ?? []).map((file) => normaliseTreePath("--approve-verification-edit", file)))];
312	  const progress = (message: string) => operator.onProgress?.(message);
313	  // Child processes run synchronously: yielding here is what lets a signal handler run between them.
314	  const checkpoint = async () => {
315	    await new Promise<void>((resolve) => setImmediate(resolve));
316	    if (operator.signal?.aborted) throw new VerifyInterrupted();
317	  };
318	
319	  const doc: Omit<VerifyJsonResult, "schema_version" | "verdict" | "outcome" | "reason" | "detail" | "exitCode" | "durationMs"> = {
320	    changedFiles: [],
321	    changedFileCount: 0,
322	    deliverables,
323	    approvedVerificationEdits: approvedEdits.map((file) => printable(file)),
324	    runs: [],
325	    typecheck: { status: "NOT_RUN", detail: "verification ended before a type-check was due" },
326	    guard: { status: "NOT_RUN", findings: [], complete: false, detail: "verification ended before the change was read" },
327	    review: { status: "NOT_RUN", detail: "this version of nexus verify has no reviewer" },
328	    linkedDependencyDirs: [],
329	    limits: { timeoutSecs, maxTreeFiles: VERIFY_MAX_TREE_FILES, maxTreeBytes: VERIFY_MAX_TREE_BYTES },
330	    environment: VERIFY_RECORDED_ENVIRONMENT.filter((name) => Boolean(process.env[name])),
331	    nexusVersion: getBuildIdentity().string,
332	    startedAt: new Date(started).toISOString(),
333	  };
334	  const finish = (outcome: VerifyJsonResult["outcome"], reason: VerifyReason | undefined, detail: string | undefined): VerifyJsonResult => {
335	    const { base, head, ...rest } = doc;
336	    return {
337	      schema_version: VERIFY_RESULT_SCHEMA_VERSION,
338	      verdict: verifyVerdictFor(reason),
339	      outcome,
340	      ...(reason === undefined ? {} : { reason }),
341	      ...(detail ? { detail: capped(safeTerminal(detail), 600) } : {}),
342	      exitCode: verifyExitCode(verifyExitNameFor(reason)),
343	      ...(base ? { base } : {}),
344	      ...(head ? { head } : {}),
345	      ...rest,
346	      durationMs: Date.now() - started,
347	    };
348	  };
349	  /**
350	   * The verdict once the guard has read the change. Precedence: a head that was run and did not pass keeps its reason
351	   * (exit 1); a verifier that was not approved keeps its (nothing ran); otherwise a guard finding that waits for a
352	   * decision, or an incomplete scan, is BLOCKED whatever the tests showed. An approved finding never blocks and never
353	   * leaves the change VERIFIED: what was approved is the report, not the weakening.
354	   */
355	  const conclude = (outcome: VerifyJsonResult["outcome"], reason: VerifyReason | undefined, detail: string | undefined): VerifyJsonResult => {
356	    const guard = doc.guard;
357	    const needing = guard.findings.filter((finding) => finding.requiresApproval);
358	    if (guard.status === "BLOCKED" && reason !== "VERIFIER_NOT_APPROVED" && !(reason && HEAD_RUN_FAILURES.includes(reason))) {
359	      const otherwise = `Without this the result was ${verifyVerdictFor(reason)}${reason && reason !== verifyVerdictFor(reason) ? ` (${reason})` : ""}.`;
360	      if (!guard.complete) return finish("UNVERIFIED", "GUARD_INCOMPLETE", `not every changed file could be classified, so the change may edit how it is verified in ways not listed: ${guard.detail}. ${otherwise}`);
361	      const waiting = needing.filter((finding) => guard.mode === "block" || !finding.approved);
362	      const listed = `${waiting.slice(0, 5).map(describeFinding).join("; ")}${waiting.length > 5 ? `; and ${waiting.length - 5} more` : ""}`;
363	      return finish("UNVERIFIED", "VERIFICATION_EDIT_BLOCKED", guard.mode === "block"
364	        ? `the change edits how it is verified, and the base tree's policy (mode block) refuses such edits: ${listed}. ${otherwise}`
365	        : `the change edits how it is verified, and the edit was not approved: ${listed}. Approve each with --approve-verification-edit <path> after reading it; approval lets the result be reported and never makes the change VERIFIED. ${otherwise}`);
366	    }
367	    if (outcome === "VERIFIED" && needing.length) {
368	      return finish("REGRESSION_FREE", "REGRESSION_FREE", `Tests pass, but the change edits how it is verified (${needing.slice(0, 5).map(describeFinding).join("; ")}${needing.length > 5 ? `; and ${needing.length - 5} more` : ""}). The approval given with --approve-verification-edit lets the result be reported; it does not make the change verified.`);
369	    }
370	    return finish(outcome, reason, detail);
371	  };
372	
373	  let worktree: string;
374	  try {
375	    worktree = fs.realpathSync(request.worktree);
376	    if (!fs.statSync(worktree).isDirectory()) throw new Error("not a directory");
377	  } catch {
378	    throw new VerifyUsageError(`${printable(request.worktree)} is not a directory`);
379	  }
380	  const baseRef = request.base ?? "HEAD";
381	  if (!validRef(baseRef)) throw new VerifyUsageError(`--base ${printable(baseRef.slice(0, 80))} is not a valid revision name`);
382	  if (request.head !== undefined && !validRef(request.head)) throw new VerifyUsageError(`--head ${printable(request.head.slice(0, 80))} is not a valid revision name`);
383	
384	  let scratch: string | undefined;
385	  try {
386	    // The checkout itself must be one Git can be run in (a planted or rewritten `.git` is refused).
387	    trustedGitArgs(worktree);
388	
389	    let gitEnvironment: Record<string, string> = {};
390	    const run = (args: string[], options: { env?: Record<string, string>; timeoutMs?: number } = {}) => {
391	      const timeoutMs = options.timeoutMs ?? GIT_TIMEOUT_MS;
392	      let result;
393	      try {
394	        result = git(worktree, args, { allowFailure: true, timeoutMs, maxBuffer: GIT_LISTING_BUFFER, env: { ...gitEnvironment, ...(options.env ?? {}) } });
395	      } catch (error) {
396	        if (error instanceof GitError && /ENOBUFS/.test(error.message)) throw new Stop("TREE_LIMIT_EXCEEDED", `the output of git ${args[0]} is larger than ${GIT_LISTING_BUFFER} bytes`);
397	        throw error;
398	      }
399	      if (result.timedOut) throw new Stop("TREE_LIMIT_EXCEEDED", `git ${args[0]} did not finish within ${timeoutMs / 1000}s`);
400	      return result;
401	    };
402	    const must = (args: string[], options: { env?: Record<string, string>; timeoutMs?: number } = {}): string => {
403	      const result = run(args, options);
404	      if (result.status !== 0) throw new Error(`git ${args[0]} failed: ${printable(result.stderr.trim().split("\n")[0] ?? "").slice(0, 300) || `exit ${result.status}`}`);
405	      return result.stdout.replace(/\n$/, "");
406	    };
407	
408	    const top = run(["rev-parse", "--show-toplevel"]);
409	    if (top.status !== 0) throw new VerifyUsageError(`${printable(worktree)} is not a Git working tree`);
410	    if (fs.realpathSync(top.stdout.replace(/\n$/, "")) !== worktree) {
