750	      const counts = project.errorCount === undefined ? "" : `, ${project.errorCount} error(s)${project.introducedCount === undefined ? "" : `, ${project.introducedCount} not on the base`}`;
751	      row("", `${project.status}: ${project.tool} ${project.scope ?? ""}${counts}`);
752	      for (const diagnostic of (project.status === "FAILED" ? project.firstDiagnostics ?? [] : []).slice(0, 3)) lines.push(`    | ${diagnostic}`);
753	    }
754	  }
755	  if (result.guard.status !== "NOT_RUN") {
756	    const policy = `mode ${result.guard.mode}, ${result.guard.policySource === "base_tree" ? "the base tree's .nexus-security.json" : "default policy"}`;
757	    row("guard", `${result.guard.status} (${policy}): ${result.guard.findings.length} changed verification file(s)${result.guard.complete ? "" : `; INCOMPLETE: ${result.guard.detail}`}`);
758	    for (const finding of result.guard.findings.slice(0, 20)) {
759	      const decision = !finding.requiresApproval ? "recorded" : result.guard.mode === "block" ? "REFUSED (mode block)" : finding.approved ? "approved by --approve-verification-edit" : "NOT APPROVED";
760	      row("", `${finding.path}: ${finding.class}, ${finding.kind}${finding.weakening ? `, weakening: ${finding.weakening.join(", ")}` : ""}; ${decision}`);
761	    }
762	    if (result.guard.findings.length > 20) row("", `and ${result.guard.findings.length - 20} more (see --json)`);
763	  }
764	  const notRun = [result.typecheck.status === "NOT_RUN" ? "type-check" : "", result.guard.status === "NOT_RUN" ? "verification-file guard" : "", "review"].filter(Boolean);
765	  row("not run", notRun.join(", "));
766	  if (result.environment.length) row("environment", `set: ${result.environment.join(", ")}`);
767	  const failed = [...result.runs].reverse().find((ran) => ran.phase === "head" && !ran.passed);
768	  if (failed?.outputTail) lines.push("  head output (end; untrusted repository output):", ...failed.outputTail.trimEnd().split("\n").slice(-30).map((line) => `    | ${line}`));
769	  lines.push(`  exit code    ${result.exitCode}`);
770	  return lines.join("\n");
771	}
