1	/**
2	 * Type-check evidence for a caller that has no agent (`nexus verify`).
3	 *
4	 * MIRROR: this reproduces how core/completion_oracle.ts turns project type-checks into TypecheckEvidence and decides
5	 * which of them stop a passing verifier from counting (`runTypecheckOracleImpl`: the per-check order, the fields of each
6	 * record, the status priority of the combined record) and how it captures the pre-change baseline
7	 * (`captureTypecheckBaselineImpl`). The two must change together until the agent adopts this module;
8	 * test/typecheck_evidence.test.ts pins this side and compares it with the agent's function on the same inputs.
9	 *
10	 * What the agent's oracle also does and this module does not, because a caller without an agent has none of it: a
11	 * separate approval of each type-check command, the attempt ledger (an unchanged failing check is not rerun), files
12	 * changed through the shell, the candidate id, and the rule for a baseline lost across a resume.
13	 *
14	 * One deliberate difference: the baseline is keyed by tool and configuration path, where the agent keys it by command.
15	 * The agent runs both sides in one directory; here they run in two, and a command can embed its directory (Cargo's
16	 * target directory), so the same project would have two commands.
17	 */
18	import { safeTerminal } from "../ui.js";
19	import { runTypecheck, type DiscoveredTypecheck, type TimedExecutor, type TypecheckMode, type TypecheckRun } from "../tester.js";
20	import { foldVoluminousOutput } from "./agent_support.js";
21	import type { TypecheckEvidence } from "./turn.js";
22	
23	type Status = TypecheckEvidence["status"];
24	
25	/** completion_oracle.ts: the combined record takes the first of these statuses that any project has. */
26	export const TYPECHECK_STATUS_PRIORITY: readonly Status[] = ["FAILED", "TIMED_OUT", "UNAVAILABLE", "NOT_APPLICABLE", "ENVIRONMENT", "PREEXISTING", "PASSED"];
27	
28	/** Why an enforced check stops a passing verifier from counting. UNAVAILABLE: it could not be run at all (no tool, a configuration this checker cannot stand for, an incomplete project scan). */
29	export type TypecheckBlockKind = "FAILED" | "TIMED_OUT" | "UNAVAILABLE";
30	
31	export interface TypecheckBlock {
32	  kind: TypecheckBlockKind;
33	  message: string;
34	}
35	
36	export interface TypecheckProjectEvidence {
37	  evidence: TypecheckEvidence;
38	  /** Present only for an enforced check that blocks. */
39	  block?: TypecheckBlock;
40	}
41	
42	/** The baseline's key for a project: the same on the base and on the head whatever directory each ran in. */
43	export const typecheckProjectKey = (check: Pick<DiscoveredTypecheck, "tool" | "configPath">): string => `${check.tool}\n${check.configPath}`;
44	
45	/**
46	 * The evidence for one discovered project. `run` is absent when the project was not run: discovery already says why
47	 * (`skipReason`, `missingTool`), or the shared budget was used up before its turn.
48	 *
49	 * Blocking, exactly as the agent decides it for an enforced check: FAILED and TIMED_OUT block; so does a check that was
50	 * never run (skipped, tool missing at discovery, budget used up). ENVIRONMENT, PREEXISTING and a tool that turned out to
51	 * be unusable when probed (UNAVAILABLE from the run) are recorded and do NOT block.
52	 */
53	export function typecheckProjectEvidence(
54	  check: DiscoveredTypecheck,
55	  enforced: boolean,
56	  attempt: { budgetSecs: number; run?: TypecheckRun; baseline?: ReadonlySet<string> },
57	  at: string,
58	): TypecheckProjectEvidence {
59	  const named = { tool: check.tool, command: check.command, configPath: check.configPath, configSha256: check.configSha256, ...(check.toolSha256 ? { toolSha256: check.toolSha256 } : {}) };
60	  const blocked = (kind: TypecheckBlockKind, message: string) => (enforced ? { block: { kind, message } } : {});
61	  if (check.skipReason) {
62	    return {
63	      evidence: { status: check.discoveryIncomplete ? "UNAVAILABLE" : "NOT_APPLICABLE", ...named, enforced, scope: check.skipReason, at },
64	      ...blocked("UNAVAILABLE", check.discoveryIncomplete
65	        ? `workspace type-check discovery was incomplete: ${check.skipReason}`
66	        : `${check.tool} type-check under ${check.configPath} was not run: ${check.skipReason}`),
67	    };
68	  }
69	  if (check.missingTool) {
70	    return {
71	      evidence: { status: "UNAVAILABLE", ...named, enforced, scope: `${check.tool} is not installed, so nothing was type-checked under ${check.configPath}`, at },
72	      ...blocked("UNAVAILABLE", `${check.tool} type-check under ${check.configPath} is unavailable because ${check.tool} is not installed.`),
73	    };
74	  }
75	  const { run, baseline, budgetSecs } = attempt;
76	  if (!run) {
77	    return {
78	      evidence: { status: "TIMED_OUT", enforced, ...named, scope: `not run: aggregate type-check budget of ${budgetSecs}s exhausted`, at },
79	      ...blocked("TIMED_OUT", `${check.tool} type-check under ${check.configPath} was not run because the aggregate ${budgetSecs}s type-check budget was exhausted.`),
80	    };
81	  }
82	  const excerpt = `(untrusted compiler output)\n${safeTerminal(foldVoluminousOutput(run.output || "", 30, 2000))}`;
83	  const evidence: TypecheckEvidence = {
84	    status: run.status, enforced, ...named,
85	    ...(run.version ? { toolVersion: run.version } : {}),
86	    exitCode: run.exitCode,
87	    ...(run.errorCount !== undefined ? { errorCount: run.errorCount, firstDiagnostics: (run.firstDiagnostics ?? []).map((d) => safeTerminal(d)) } : {}),
88	    ...(baseline ? { baselineErrorCount: baseline.size } : {}),
89	    ...(run.introducedCount !== undefined ? { introducedCount: run.introducedCount } : {}),
90	    scope: `under ${check.configPath}`,
91	    ...(run.status === "PASSED" ? {} : { excerpt }),
92	    at,
93	  };
94	  if (run.status !== "FAILED" && run.status !== "TIMED_OUT") return { evidence };
95	  return {
96	    evidence,
97	    ...blocked(run.status, `${check.tool} type-check ${run.status === "FAILED" ? "failed" : `timed out after ${budgetSecs}s`} under ${check.configPath} (sha256 ${check.configSha256.slice(0, 12)}). Command: ${check.command}\n${excerpt}`),
98	  };
99	}
100	
101	/** The one record for all projects: the highest-priority project's fields, with every project under `projects`. */
102	export function combineTypecheckEvidence(results: readonly TypecheckEvidence[]): TypecheckEvidence {
103	  const primary = TYPECHECK_STATUS_PRIORITY.map((status) => results.find((item) => item.status === status)).find((item) => item !== undefined) ?? results[0];
104	  return { ...primary, scope: results.length === 1 ? primary.scope : `${results.length} project check(s)`, projects: [...results] };
105	}
106	
107	/** The record when nothing was checked and nothing is wrong with that: type-checking is off, or the tree has no project. */
108	export function typecheckNotApplicable(mode: TypecheckMode, at: string): TypecheckEvidence {
109	  return { status: "NOT_APPLICABLE", scope: mode === "off" ? "disabled by NEXUS_TYPECHECK / typecheck setting" : "no configured type-check project found", at };
110	}
111	
112	/** The reason an enforced type-check gives, the worst first; undefined when nothing blocks. */
113	export function worstTypecheckBlock(blocks: readonly TypecheckBlock[]): TypecheckBlock | undefined {
114	  return (["FAILED", "TIMED_OUT", "UNAVAILABLE"] as const).map((kind) => blocks.find((block) => block.kind === kind)).find((block) => block !== undefined);
115	}
116	
117	export interface TypecheckBaselineRecord {
118	  tool: string;
119	  configPath: string;
120	  /** NOT_RUN: discovery already ruled the project out (skipped, or its tool is missing). */
121	  status: TypecheckRun["status"] | "NOT_RUN";
122	  /** Located errors on the base; present when the base run can serve as a baseline. */
123	  errorCount?: number;
124	}
125	
126	/**
127	 * The errors that exist before the change, per project (captureTypecheckBaselineImpl): a base run that passed gives an
128	 * empty set, one whose errors are all located gives their signatures, and any other run gives no baseline, so on the
129	 * head an error in an untouched file then counts as it would without one (PREEXISTING).
130	 */
131	export async function captureTypecheckBaseline(input: {
132	  checks: readonly DiscoveredTypecheck[];
133	  execute: TimedExecutor;
134	  workspace: string;
135	  deadlineSecs: number;
136	}): Promise<{ baselines: Map<string, ReadonlySet<string>>; records: TypecheckBaselineRecord[] }> {
137	  const baselines = new Map<string, ReadonlySet<string>>();
138	  const records: TypecheckBaselineRecord[] = [];
139	  for (const check of input.checks) {
140	    const named = { tool: check.tool, configPath: check.configPath };
141	    if (check.skipReason || check.missingTool) {
142	      records.push({ ...named, status: "NOT_RUN" });
143	      continue;
144	    }
145	    const run = await runTypecheck(check, input.execute, input.workspace, new Set(), input.deadlineSecs);
146	    const signatures = run.status === "PASSED" ? new Set<string>() : run.status === "PREEXISTING" ? new Set(run.signatures ?? []) : undefined;
147	    if (signatures) baselines.set(typecheckProjectKey(check), signatures);
148	    records.push({ ...named, status: run.status, ...(signatures ? { errorCount: signatures.size } : {}) });
149	  }
150	  return { baselines, records };
151	}
152	
153	/**
154	 * Runs every discovered project against one shared budget and returns the combined evidence and what blocks
155	 * (runTypecheckOracleImpl). `checks` must not be empty. `modified` holds absolute paths inside `workspace`.
156	 */
157	export async function collectTypecheckEvidence(input: {
158	  checks: readonly DiscoveredTypecheck[];
159	  enforced: boolean;
160	  execute: TimedExecutor;
161	  workspace: string;
162	  modified: ReadonlySet<string>;
163	  budgetSecs: number;
164	  baselines?: ReadonlyMap<string, ReadonlySet<string>>;
165	  now?: () => number;
166	}): Promise<{ evidence: TypecheckEvidence; blocks: TypecheckBlock[] }> {
167	  const now = input.now ?? Date.now;
168	  const at = () => new Date(now()).toISOString();
169	  const deadline = now() + Math.max(0, input.budgetSecs) * 1000;
170	  const results: TypecheckEvidence[] = [];
171	  const blocks: TypecheckBlock[] = [];
172	  for (const check of input.checks) {
173	    const baseline = input.baselines?.get(typecheckProjectKey(check));
174	    let run: TypecheckRun | undefined;
175	    if (!check.skipReason && !check.missingTool) {
176	      const remainingSecs = Math.ceil((deadline - now()) / 1000);
177	      if (remainingSecs > 0) run = await runTypecheck(check, input.execute, input.workspace, input.modified, remainingSecs, baseline);
178	    }
179	    const project = typecheckProjectEvidence(check, input.enforced, { budgetSecs: input.budgetSecs, run, baseline }, at());
180	    results.push(project.evidence);
181	    if (project.block) blocks.push(project.block);
182	  }
183	  return { evidence: combineTypecheckEvidence(results), blocks };
184	}
