1	/**
2	 * VR-1: `nexus verify`, the verdict on a change that Nexus did not necessarily make: a working tree against a commit,
3	 * or one commit against another. No model is involved.
4	 *
5	 * Both sides are materialised into scratch directories (the caller's checkout is never written), the verifier is taken
6	 * from the operator or discovered in the BASE tree (the head is the change under test and cannot choose its own judge),
7	 * it is run on the base and on the head, and the outcome is derived by the same rules the agent applies to its own
8	 * work: this module re-composes captureChangeBaselineImpl / judgeIndependenceImpl (core/completion_oracle.ts) and the
9	 * evidence built in core/spine_handlers.ts, and derives the outcome with outcomeFromEvidence. The project type-checks
10	 * run on both sides as the agent's oracle runs them (core/typecheck_evidence.ts), and every changed file that defines
11	 * or weakens the verification is a guard finding, classified under the BASE tree's policy.
12	 *
13	 * Where each thing is read: the guard reads both trees before any repository code has run in them; the verifier runs in
14	 * `base` and `head`; the type-checks run in copies of their own (`base-typecheck`, `head-typecheck`), because a checker
15	 * may write build output; and the head is judged on `head-pristine`, a copy nothing has run in.
16	 *
17	 * Authority: the request names only what to compare. Everything that can raise the verdict (the verifier command, its
18	 * approval, the declared deliverables, the deadline) comes from the operator context. Anything that cannot be fully
19	 * evaluated lowers the verdict with a reason that names it; nothing here raises one.
20	 */
21	import fs from "node:fs";
22	import os from "node:os";
23	import path from "node:path";
24	import { createHash } from "node:crypto";
25	import { getBuildIdentity } from "../build_identity.js";
26	import { trustedGitArgs } from "../git.js";
27	import { SecurityManager, conditionalConfigChanged, isConditionalConfig, neutersTests } from "../security.js";
28	import {
29	  MAX_TEST_BYTES, SKIP_DIRS, describeVerifier, discoverTypechecks, discoverVerifier, hasExecutedTests, isFilteredVerifierCommand, isVerifierDeliverableBound,
30	  runVerifierShell, typecheckMode, verifierTimeoutSecs, type DiscoveredTypecheck, type TimedExecutor,
