139	const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");
140	const capped = (text: string, max: number) => (text.length > max ? `${text.slice(0, max)}…` : text);
141	
142	function validRef(ref: string): boolean {
143	  return ref.length > 0 && ref.length <= 256 && !ref.startsWith("-") && !/[\0\r\n]/.test(ref);
144	}
145	
146	/** An operator-named file as a normalised workspace-relative path; a path that is absolute or leaves the tree is refused. */
147	function normaliseTreePath(option: string, file: string): string {
148	  const normal = path.posix.normalize(file.trim().replace(/\\/g, "/")).replace(/^\.\//, "");
149	  if (!normal || normal === "." || normal.startsWith("../") || normal === ".." || path.isAbsolute(normal) || /[\0\r\n]/.test(normal)) {
150	    throw new VerifyUsageError(`${option} ${printable(file)} is not a path inside the working tree`);
151	  }
152	  return normal;
153	}
