724	  if (result.detail) row("why", result.detail);
725	  if (result.base) row("base", side(result.base));
726	  if (result.head) row("head", `${side(result.head)}, ${result.changedFileCount} changed file(s)`);
727	  if (result.verifier) {
728	    const approvals: Record<VerifyVerifierRecord["approval"], string> = { operator_command: "the operator's --verifier", yes: "approved by --yes", digest: "approved by --approve-verifier", none: "NOT APPROVED" };
