112	/** The reason an enforced type-check gives, the worst first; undefined when nothing blocks. */
113	export function worstTypecheckBlock(blocks: readonly TypecheckBlock[]): TypecheckBlock | undefined {
114	  return (["FAILED", "TIMED_OUT", "UNAVAILABLE"] as const).map((kind) => blocks.find((block) => block.kind === kind)).find((block) => block !== undefined);
115	}
