29	/**
30	 * Write-mode `--sandbox` masks $HOME with an empty tmpfs and binds back, read-only, only the toolchain directories a
31	 * build needs. Credential locations are never bound, whatever the PATH or the operator's list says.
32	 */
33	const HOME_TOOLCHAIN_DEFAULTS = [
34	  ".cargo", ".rustup", ".nvm", ".local/bin", ".npm", ".cache/pip", "go/pkg",
35	];
36	/** Under HOME. A candidate that is one of these, inside one, or the parent of one is refused. */
37	const HOME_DENIED = [
38	  ".ssh", ".gnupg", ".aws", ".config/nexus", ".config/gh", ".netrc", ".docker", ".kube", ".azure", ".npmrc",
39	  ".pypirc", ".gitconfig", ".git-credentials", ".config/gcloud", ".config/google-chrome", ".config/chromium",
40	  ".config/BraveSoftware", ".config/microsoft-edge", ".mozilla", ".config/mozilla",
41	  ".config", ".local/share", ".local", ".cache",
42	];
43	/** Allowed roots may contain these files (cargo keeps its registry token in ~/.cargo); they are masked. */
44	const HOME_MASKED_FILES = [".cargo/credentials", ".cargo/credentials.toml"];
45	/** Broad directories: refused as a whole (or as a parent), while a specific safe child such as ~/.cache/pip is allowed. */
46	const BROAD_DENIED = new Set([".config", ".local/share", ".local", ".cache"]);
47	export const SANDBOX_HOME_READONLY_SETTING = "NEXUS_SANDBOX_HOME_READONLY";
48	export const SANDBOX_NETWORK_SETTING = "NEXUS_SANDBOX_NETWORK";
