50	/**
51	 * The Docker sandbox image. The pin lives here and nowhere else: a floating tag (`alpine:latest`) lets whoever controls
52	 * the registry change what runs the agent's commands. This is the multi-arch index digest of alpine 3.23, resolved
53	 * from the registry (`docker buildx imagetools inspect alpine:3.23`) on 2026-11-15. Refresh it deliberately, never to
54	 * a tag. The operator may substitute their own image with NEXUS_SANDBOX_DOCKER_IMAGE (operator environment or
55	 * config.env, never a project .env); it must also be pinned by digest or no container is started.
56	 */
57	export const DOCKER_SANDBOX_IMAGE = "alpine:3.23@sha256:469c9ea410b9215eaee7976ba6c0639039b444be8e5d638f7abbada189971eb2";
58	export const DOCKER_SANDBOX_IMAGE_SETTING = "NEXUS_SANDBOX_DOCKER_IMAGE";
59	const PINNED_IMAGE = /^[^\s@]+@sha256:[0-9a-f]{64}$/;
60	const DOCKER_PIDS_LIMIT = "512";
