62	/** The image to run, or undefined when the operator's override is not digest-pinned (fail closed). */
63	export function dockerSandboxImage(): string | undefined {
64	  const configured = operatorSetting(DOCKER_SANDBOX_IMAGE_SETTING)?.trim();
65	  if (!configured) return DOCKER_SANDBOX_IMAGE;
66	  return PINNED_IMAGE.test(configured) ? configured : undefined;
67	}
