249	function appendDirectoryTree(args: string[], target: string, known: Set<string>): void {
250	  const absolute = path.resolve(target);
251	  const parts = absolute.split(path.sep).filter(Boolean);
252	  let current = path.parse(absolute).root;
253	  for (const part of parts) {
254	    current = path.join(current, part);
255	    if (!known.has(current)) {
256	      args.push("--dir", current);
257	      known.add(current);
258	    }
259	  }
260	}
