354	/** Exercise the actual mount boundary, not just the presence of a binary. */
355	function probeBwrapSandbox(): boolean {
356	  if (!isBwrapAvailable()) return false;
357	  const root = fs.mkdtempSync(path.join(os.homedir(), ".nexus-bwrap-probe-"));
358	  const workspace = path.join(root, "workspace");
359	  const outside = path.join(root, "outside.txt");
360	  try {
361	    fs.mkdirSync(workspace);
362	    fs.writeFileSync(outside, "protected");
363	    const probe = wrapSandboxedCommand(`printf escaped > ${JSON.stringify(outside)}; printf writable > probe.txt`, workspace, { mode: "bwrap" });
364	    if (!probe.sandboxed) return false;
365	    if (!probe.argv?.length) return false;
366	    execFileSync(probe.argv[0], probe.argv.slice(1), { stdio: "ignore", timeout: 5000 });
367	    return fs.readFileSync(outside, "utf8") === "protected"
368	      && fs.readFileSync(path.join(workspace, "probe.txt"), "utf8") === "writable";
369	  } catch {
370	    return false;
371	  } finally {
372	    fs.rmSync(root, { recursive: true, force: true });
373	  }
374	}
