376	/** Verify Docker can actually launch the configured image and mount boundary. */
377	function probeDockerSandbox(): boolean {
378	  if (!isDockerAvailable()) return false;
379	  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-docker-probe-"));
380	  const workspace = path.join(root, "workspace");
381	  try {
382	    fs.mkdirSync(workspace);
383	    const probe = wrapSandboxedCommand("printf writable > probe.txt", workspace, { mode: "docker" });
384	    if (!probe.sandboxed) return false;
385	    if (!probe.argv?.length) return false;
386	    execFileSync(probe.argv[0], probe.argv.slice(1), { stdio: "ignore", timeout: 60000 }); // first run may pull the pinned image
387	    return fs.readFileSync(path.join(workspace, "probe.txt"), "utf8") === "writable";
388	  } catch {
389	    return false;
390	  } finally {
391	    fs.rmSync(root, { recursive: true, force: true });
392	  }
393	}
