395	/**
396	 * Wrap a shell command in Linux container / namespace sandboxing (Candidate #33)
397	 * Restricts mutating filesystem access to the target workspace directory.
398	 */
399	export interface SandboxedWorkerLaunch {
400	  /** The program and arguments to spawn: `bwrap ...` or `docker run ...` ending in the worker command. */
401	  command?: string;
402	  args?: string[];
403	  sandboxed: boolean;
404	  engine: SandboxedCommandResult["engine"];
405	  warning?: string;
406	}
407	
408	export interface SandboxedWorkerOptions extends Pick<SandboxOptions, "network"> {
409	  /** Engines to try, in order. Default: Bubblewrap only. */
410	  engines?: readonly ("bwrap" | "docker")[];
411	}
