413	/**
414	 * CS-10: launches a long-lived worker (the native core) inside the sandbox a command would get: a read-only root, the
415	 * workspace the only writable path, $HOME masked, a scrubbed environment, no network unless the operator allowed it, and
416	 * the worker ends with its parent. The worker's commands then run in the same box, so the per-command wrap is not
417	 * applied a second time.
418	 *
419	 * The first engine in `options.engines` that can build the box is used; with none, the result is unsandboxed with the
420	 * reasons, and the caller decides whether that is a refusal.
421	 */
422	export function wrapSandboxedWorker(
423	  workerPath: string,
424	  workerArgs: readonly string[],
425	  workspace: string,
426	  options: SandboxedWorkerOptions = {},
427	): SandboxedWorkerLaunch {
428	  const warnings: string[] = [];
429	  for (const engine of options.engines ?? ["bwrap"]) {
430	    const launch = engine === "bwrap"
431	      ? wrapBwrapWorker(workerPath, workerArgs, workspace, options)
432	      : wrapDockerWorker(workerPath, workerArgs, workspace, options);
433	    if (launch.sandboxed) return launch;
434	    if (launch.warning) warnings.push(launch.warning);
435	  }
436	  return { sandboxed: false, engine: "none", warning: warnings.join(" ") || "No sandbox engine was requested for the worker." };
437	}
