439	/** The worker's own directory is bound read-only because it may live under the masked $HOME (a checkout or a per-user install). */
440	function wrapBwrapWorker(workerPath: string, workerArgs: readonly string[], workspace: string, options: SandboxedWorkerOptions): SandboxedWorkerLaunch {
441	  if (!isBwrapAvailable()) {
442	    return { sandboxed: false, engine: "none", warning: "Bubblewrap (bwrap) is not available, so the worker cannot be isolated." };
443	  }
444	  const exec = `exec ${[workerPath, ...workerArgs].map(quoteForShell).join(" ")}`;
445	  const wrapped = wrapSandboxedCommand(exec, workspace, {
446	    mode: "bwrap",
447	    shell: "bash",
448	    network: options.network,
449	    customBwrapArgs: ["--ro-bind", path.dirname(workerPath), path.dirname(workerPath)],
450	  });
451	  if (!wrapped.sandboxed || wrapped.engine !== "bwrap" || !wrapped.argv?.length) {
452	    return { sandboxed: false, engine: wrapped.engine, warning: wrapped.warning ?? "The Bubblewrap profile could not be built for the worker." };
453	  }
454	  return { command: wrapped.argv[0], args: wrapped.argv.slice(1), sandboxed: true, engine: "bwrap" };
455	}
