508	/**
509	 * Resolve the worker's ELF interpreter and shared libraries without executing the worker. `ldd` can run the target's
510	 * interpreter on some systems, so it is unsafe for a binary that an agent may have replaced inside its workspace.
511	 * `readelf` only parses metadata; `ldconfig -p` supplies the host's cached library paths. Unknown dependencies fail
512	 * closed. Static workers need no host runtime files.
513	 */
514	export function workerRuntimeFiles(workerPath: string): { loader?: string; libraries: string[]; libraryNames: Array<{ name: string; path: string }> } | { error: string } {
515	  if (process.platform !== "linux") return { error: "worker runtime discovery is supported only on Linux." };
516	  const readelf = trustedSystemTool("readelf");
517	  if (!readelf) return { error: "a trusted system readelf executable is unavailable." };
518	
519	  let resolvedWorker: string;
520	  try {
521	    resolvedWorker = fs.realpathSync(workerPath);
522	    if (!fs.statSync(resolvedWorker).isFile()) return { error: "the worker path is not a regular file." };
523	  } catch (err: any) {
524	    return { error: `the worker binary is missing: ${err?.message ?? err}` };
525	  }
526	
527	  const initial = readElfRuntimeInfo(readelf, resolvedWorker);
528	  if ("error" in initial) return initial;
529	  const machineTags = ({ x64: ["x86-64"], arm64: ["aarch64"], arm: ["arm"], ia32: ["80386"] } as Record<string, string[]>)[process.arch] ?? [];
530	  if (!machineTags.some((tag) => initial.machine.toLowerCase().includes(tag))) {
531	    return { error: `the worker architecture (${initial.machine}) does not match the host architecture (${process.arch}).` };
532	  }
533	  if (!initial.interpreter && initial.needed.length === 0) return { libraries: [], libraryNames: [] };
534	  if (!initial.interpreter) return { error: "the dynamically linked worker has no ELF interpreter." };
535	
536	  const ldconfig = trustedSystemTool("ldconfig");
537	  if (!ldconfig) return { error: "a trusted system ldconfig executable is unavailable for shared-library resolution." };
538	  let cacheOutput: string;
539	  try {
540	    cacheOutput = execFileSync(ldconfig, ["-p"], {
541	      encoding: "utf8",
542	      timeout: 5_000,
543	      stdio: ["ignore", "pipe", "pipe"],
544	      env: { LC_ALL: "C", PATH: "/usr/bin:/bin:/usr/sbin:/sbin" },
545	    });
546	  } catch (err: any) {
547	    return { error: `system shared-library paths could not be read (ldconfig failed: ${String(err?.message ?? err).split("\n")[0]}).` };
548	  }
549	
550	  const architecture = ({ x64: ["x86-64", "x86_64"], arm64: ["aarch64"], arm: ["arm"], ia32: ["80386"] } as Record<string, string[]>)[process.arch] ?? [];
551	  const cache = new Map<string, string[]>();
552	  for (const line of cacheOutput.split("\n")) {
553	    const match = line.match(/^\s*(\S+)\s+\(([^)]+)\)\s+=>\s+(\S+)\s*$/);
554	    if (!match || !architecture.some((tag) => match[2].toLowerCase().includes(tag))) continue;
555	    const paths = cache.get(match[1]) ?? [];
556	    paths.push(match[3]);
557	    cache.set(match[1], paths);
558	  }
559	
560	  const loaderPath = initial.interpreter;
561	  let loader: string | undefined;
562	  if (loaderPath) {
563	    try {
564	      loader = fs.realpathSync(loaderPath);
565	      if (!fs.statSync(loader).isFile()) return { error: "the worker's ELF interpreter is not a regular file." };
566	    } catch (err: any) {
567	      return { error: `the worker's ELF interpreter is missing: ${err?.message ?? err}` };
568	    }
569	  }
570	
571	  const libraries = new Set<string>();
572	  const libraryNames = new Map<string, string>();
573	  const scanned = new Set<string>([resolvedWorker]);
574	  const queue: Array<{ file: string; info: ElfRuntimeInfo }> = [{ file: resolvedWorker, info: initial }];
575	  const resolveNeeded = (name: string, searchPaths: string[]): string | undefined => {
576	    const candidates = name.includes("/")
577	      ? (path.isAbsolute(name) ? [name] : [])
578	      : [...searchPaths.map((directory) => path.join(directory, name)), ...(cache.get(name) ?? [])];
579	    for (const candidate of candidates) {
580	      try {
581	        const resolved = fs.realpathSync(candidate);
582	        if (fs.statSync(resolved).isFile()) return resolved;
583	      } catch {
584	        // Try the next candidate; never guess when a needed library is absent.
585	      }
586	    }
587	    return undefined;
588	  };
589	
590	  while (queue.length) {
591	    const current = queue.shift()!;
592	    for (const name of current.info.needed) {
593	      if (name !== path.basename(name) || !/^[A-Za-z0-9_.+-]+$/.test(name)) {
594	        return { error: `the worker has an unsafe shared-library name: ${name}` };
595	      }
596	      const resolved = resolveNeeded(name, current.info.searchPaths);
597	      if (!resolved) return { error: `the worker needs a shared library that could not be resolved: ${name}` };
598	      const previous = libraryNames.get(name);
599	      if (previous && previous !== resolved) return { error: `the worker's shared-library name is ambiguous: ${name}` };
600	      libraryNames.set(name, resolved);
601	      libraries.add(resolved);
602	      if (libraries.size > 256) return { error: "the worker has more than 256 shared runtime files; refusing an unbounded mount set." };
603	      if (scanned.has(resolved)) continue;
604	      scanned.add(resolved);
605	      const info = readElfRuntimeInfo(readelf, resolved);
606	      if ("error" in info) return info;
607	      if (!machineTags.some((tag) => info.machine.toLowerCase().includes(tag))) {
608	        return { error: `shared library ${name} has an incompatible architecture (${info.machine}).` };
609	      }
610	      queue.push({ file: resolved, info });
611	    }
612	  }
613	  return { ...(loader ? { loader } : {}), libraries: [...libraries], libraryNames: [...libraryNames].map(([name, file]) => ({ name, path: file })) };
614	}
