616	/**
617	 * CS-10 (Docker): the worker as the long-lived process of one hardened container, built from the same `docker run`
618	 * arguments a sandboxed command gets (unprivileged uid, no capabilities, read-only root, no network unless allowed, the
619	 * workspace the only host directory). `--interactive` carries the JSON-RPC stream; `--init` reaps the commands the
620	 * worker starts and forwards signals; the container ends when the worker does (its client closing stdin ends the worker).
621	 */
622	function wrapDockerWorker(workerPath: string, workerArgs: readonly string[], workspace: string, options: SandboxedWorkerOptions): SandboxedWorkerLaunch {
623	  const refuse = (warning: string): SandboxedWorkerLaunch => ({ sandboxed: false, engine: "none", warning });
624	  if (process.platform !== "linux") return refuse("The worker can only run in a Docker container on a Linux host.");
625	  // The CLI being installed is not enough for a long-lived worker: with the daemon down the container would never start
626	  // and every tool would fail. Ask the daemon, so `auto` can fall back and an explicit `docker` refuses with the reason.
627	  try {
628	    execFileSync("docker", ["version", "--format", "{{.Server.Version}}"], { stdio: ["ignore", "ignore", "ignore"], timeout: 5000 });
629	  } catch {
630	    return refuse("The Docker daemon is not reachable, so the worker cannot run in a container.");
631	  }
632	  const placeholder = "true";
633	  const wrapped = wrapSandboxedCommand(placeholder, workspace, { mode: "docker", network: options.network });
634	  if (!wrapped.sandboxed || wrapped.engine !== "docker" || !wrapped.argv?.length) {
635	    return refuse(wrapped.warning ?? "The Docker sandbox could not be built for the worker.");
636	  }
637	  // The command form ends `-w <workspace> <image> sh -c <cmd>`; everything before the image is the hardened profile.
638	  const tail = wrapped.argv.slice(-6);
639	  const absWorkspace = path.resolve(workspace);
640	  if (tail[0] !== "-w" || tail[1] !== absWorkspace || tail[3] !== "sh" || tail[4] !== "-c" || tail[5] !== placeholder || wrapped.argv[1] !== "run") {
641	    return refuse("The Docker sandbox arguments have an unexpected shape; refusing to start the worker in a container built from them.");
642	  }
643	  const image = tail[2];
644	  const runtime = workerRuntimeFiles(workerPath);
645	  if ("error" in runtime) return refuse(`The worker cannot run in a Docker container: ${runtime.error}.`);
646	  const mounts: string[] = [];
647	  const names = new Set<string>();
648	  const mount = (host: string, name: string) => {
649	    if (names.has(name)) return;
650	    names.add(name);
651	    mounts.push("-v", `${host}:${DOCKER_WORKER_RUNTIME}/${name}:ro`);
652	  };
653	  let resolvedWorker: string;
654	  try {
655	    resolvedWorker = fs.realpathSync(workerPath);
656	  } catch (err: any) {
657	    return refuse(`The worker binary is missing: ${err?.message ?? err}.`);
658	  }
659	  mount(resolvedWorker, "harness-core");
660	  for (const library of runtime.libraries) mount(library, path.basename(library));
661	  for (const library of runtime.libraryNames) mount(library.path, library.name);
662	  const inContainer = `${DOCKER_WORKER_RUNTIME}/harness-core`;
663	  const start = runtime.loader
664	    ? (mount(runtime.loader, "ld.so"), [`${DOCKER_WORKER_RUNTIME}/ld.so`, "--library-path", DOCKER_WORKER_RUNTIME, inContainer])
665	    : [inContainer];
666	  const profile = wrapped.argv.slice(2, -6);
667	  return {
668	    command: "docker",
669	    // The label names the CLI process that owns the container, so a leftover can be found (`docker ps --filter label=...`).
670	    args: ["run", "--interactive", "--init", "--label", `${DOCKER_WORKER_LABEL}=${process.pid}`, ...profile, ...mounts, "-w", absWorkspace, image, ...start, ...workerArgs],
671	    sandboxed: true,
672	    engine: "docker",
673	  };
674	}
