676	export function wrapSandboxedCommand(
677	  cmd: string,
678	  workspace: string,
679	  options: SandboxOptions = {}
680	): SandboxedCommandResult {
681	  const mode = options.mode || "auto";
682	  const absWorkspace = path.resolve(workspace);
683	  const shell = options.shell || "bash";
684	
685	  if (mode === "none") {
686	    return {
687	      command: cmd,
688	      sandboxed: false,
689	      engine: "none",
690	    };
691	  }
692	
693	  // 1. Try Bubblewrap (bwrap)
694	  if (mode === "bwrap" || (mode === "auto" && isBwrapAvailable())) {
695	    if (!isBwrapAvailable() && mode === "bwrap") {
696	      return {
697	        command: cmd,
698	        sandboxed: false,
699	        engine: "none",
700	        warning: "Bubblewrap (bwrap) is requested but not found in PATH.",
701	      };
702	    }
703	
704	    const userHome = path.resolve(process.env.HOME || os.homedir());
705	    const bwrapArgs: string[] = ["bwrap"];
706	    const networkAllowed = !options.readOnlyHost && options.network !== false && (options.network === true || sandboxNetworkEnabled());
707	
708	    if (options.readOnlyHost) {
709	      if (!Number.isInteger(options.workspaceFd) || options.workspaceFd! < 3) {
710	        return {
711	          command: cmd,
712	          sandboxed: false,
713	          engine: "none",
714	          warning: "Read-only Bubblewrap requires a pinned workspace directory descriptor.",
715	        };
716	      }
717	      // Do not expose the host root to read-only commands. A path admitted by the
718	      // authority check can be replaced before the shell opens it; a read-only
719	      // bind of / still lets that race disclose unrelated host files.
720	      bwrapArgs.push("--unshare-pid");
721	      if (options.customBwrapArgs?.length) {
722	        return {
723	          command: cmd,
724	          sandboxed: false,
725	          engine: "none",
726	          warning: "Custom Bubblewrap mounts are incompatible with read-only host confinement.",
727	        };
728	      }
729	
730	      bwrapArgs.push("--tmpfs", "/");
731	      const knownDirectories = new Set<string>(["/"]);
732	      for (const mountpoint of ["/dev", "/proc", "/tmp"]) {
733	        appendDirectoryTree(bwrapArgs, mountpoint, knownDirectories);
734	      }
735	
736	      const homeIsUsable = userHome !== "/";
737	      if (homeIsUsable) {
738	        appendDirectoryTree(bwrapArgs, userHome, knownDirectories);
739	      }
740	      const workspaceNeedsLaterCreation =
741	        isPathWithin(absWorkspace, "/tmp") ||
742	        (homeIsUsable && isPathWithin(absWorkspace, userHome));
743	      if (!workspaceNeedsLaterCreation) {
744	        appendDirectoryTree(bwrapArgs, absWorkspace, knownDirectories);
745	      }
746	
747	      appendReadOnlyRuntime(bwrapArgs, knownDirectories);
748	      // Make the completed synthetic root read-only after creating its exact runtime mounts.
749	      bwrapArgs.push("--remount-ro", "/");
750	      bwrapArgs.push("--dev", "/dev", "--proc", "/proc", "--tmpfs", "/tmp");
751	
752	      if (homeIsUsable && userHome !== "/tmp") {
753	        if (isPathWithin(userHome, "/tmp")) {
754	          appendDirectoryTree(bwrapArgs, userHome, new Set(["/", "/tmp"]));
755	        }
756	        bwrapArgs.push("--tmpfs", userHome);
757	      }
758	
759	      if (workspaceNeedsLaterCreation) {
760	        const containingMount = homeIsUsable && isPathWithin(absWorkspace, userHome) ? userHome : "/tmp";
761	        appendDirectoryTree(bwrapArgs, absWorkspace, new Set(["/", containingMount]));
762	      }
763	      // Bind through inherited fd 3 so a rename or replacement of the source
764	      // pathname cannot redirect Bubblewrap to a different directory.
765	      bwrapArgs.push("--ro-bind", "/proc/self/fd/3", absWorkspace);
766	      bwrapArgs.push("--clearenv");
767	      bwrapArgs.push("--setenv", "PATH", "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin");
768	      bwrapArgs.push("--setenv", "HOME", "/tmp");
769	    } else {
770	      // General worktree sandbox retains the host runtime read-only while allowing
771	      // writes only through its dedicated workspace bind.
772	      bwrapArgs.push(
773	        "--ro-bind", "/", "/",
774	        "--remount-ro", "/",
775	        "--dev", "/dev",
776	        "--proc", "/proc",
777	        "--tmpfs", "/tmp",
778	      );
779	      // Mask $HOME (~/.ssh, ~/.aws, ~/.gnupg, ~/.config/nexus, browser profiles ...) the way the read-only branch does,
780	      // then bind back only the toolchain directories builds need. The tmpfs comes before the workspace bind, so a
781	      // workspace under $HOME is still bound writable on top of it.
782	      const home = sandboxHomeMounts();
783	      if (home.home !== "/" && home.home !== "/tmp") {
784	        bwrapArgs.push("--tmpfs", home.home);
785	        for (const mount of home.mounts) bwrapArgs.push("--ro-bind", mount.path, mount.path);
786	        for (const file of home.masked) bwrapArgs.push("--ro-bind", "/dev/null", file);
787	      }
788	      // Credential-bearing sockets (ssh/gpg agents, the user bus) and the container engine's control socket.
789	      if (typeof process.getuid === "function" && fs.existsSync(`/run/user/${process.getuid()}`)) {
790	        bwrapArgs.push("--tmpfs", `/run/user/${process.getuid()}`);
791	      }
792	      for (const socket of ["/run/docker.sock", "/var/run/docker.sock"]) {
793	        try {
794	          if (fs.lstatSync(socket).isSocket()) bwrapArgs.push("--ro-bind", "/dev/null", socket);
795	        } catch {
796	          // Not present.
797	        }
798	      }
799	      bwrapArgs.push("--bind", absWorkspace, absWorkspace);
800	      // The workspace bind above would re-expose credential paths when the workspace is, or contains, $HOME.
801	      const overlays = sandboxWorkspaceOverlays(absWorkspace);
802	      for (const dir of overlays.dirs) bwrapArgs.push("--tmpfs", dir);
803	      for (const file of overlays.files) bwrapArgs.push("--ro-bind", "/dev/null", file);
804	      // bwrap passes its own environment to the command. Start empty and set back only the scrubbed command
805	      // environment, so a sandboxed command cannot see the operator's credentials either (read-only branch above
806	      // already starts from --clearenv with a fixed PATH/HOME).
807	      bwrapArgs.push("--clearenv");
808	      for (const [name, value] of Object.entries(buildCommandEnvironment())) {
809	        bwrapArgs.push("--setenv", name, value);
810	      }
811	    }
812	
813	    // --die-with-parent: every descendant dies with the runner. --unshare-pid plus the fresh /proc mounted above
814	    // keep host processes, and their /proc/<pid>/environ, out of sight.
815	    // Deliberately NOT --new-session: it makes bwrap its own session leader (pgid = sid = pid), so the runner's
816	    // killpg on cancel or deadline (REQ-AGT-109, REQ-SEC-106) no longer reaches the sandboxed command, which then
817	    // survives cancellation. What it would add, blocking TIOCSTI keystroke injection, is already closed by the
818	    // kernel default since 6.2 (dev.tty.legacy_tiocsti=0). The command keeps its controlling terminal, so
819	    // /dev/tty works as before.
820	    bwrapArgs.push("--chdir", absWorkspace, "--unshare-pid", "--die-with-parent");
821	
822	    // No network unless the operator opted in explicitly (read-only mode always passes network: false).
823	    if (!networkAllowed) {
824	      bwrapArgs.push("--unshare-net");
825	    }
826	
827	    if (!options.readOnlyHost && options.customBwrapArgs && options.customBwrapArgs.length > 0) {
828	      bwrapArgs.push(...options.customBwrapArgs);
829	    }
830	
831	    // Format final execution - for argv array, raw strings are used without extra quotes
832	    bwrapArgs.push(shell, "-c", cmd);
833	
834	    return {
835	      command: bwrapArgs.map(quoteForShell).join(" "),
836	      argv: [...bwrapArgs],
837	      sandboxed: true,
838	      engine: "bwrap",
839	    };
840	  }
841	
842	  // 2. Try Docker container isolation
843	  if (mode === "docker" || (mode === "auto" && isDockerAvailable())) {
844	    if (options.readOnlyHost) {
845	      return {
846	        command: cmd,
847	        sandboxed: false,
848	        engine: "none",
849	        warning: "Read-only host confinement requires Bubblewrap with a pinned workspace descriptor; Docker path mounts are not supported.",
850	      };
851	    }
852	    if (!isDockerAvailable() && mode === "docker") {
853	      return {
854	        command: cmd,
855	        sandboxed: false,
856	        engine: "none",
857	        warning: "Docker is requested but not available or daemon is not running.",
858	      };
859	    }
860	
861	    const image = dockerSandboxImage();
862	    if (!image) {
863	      return {
864	        command: cmd,
865	        sandboxed: false,
866	        engine: "none",
867	        warning: `${DOCKER_SANDBOX_IMAGE_SETTING} must name an image pinned by digest (name@sha256:<64 hex>); refusing to run an unpinned image.`,
868	      };
869	    }
870	
871	    // Hardened `docker run`: unprivileged host uid, no capabilities, no setuid escalation, read-only root with a
872	    // writable /tmp tmpfs, bounded process count, no network unless the operator opted in (same switch as bwrap).
873	    const networkAllowed = options.network !== false && (options.network === true || sandboxNetworkEnabled());
874	    const dockerArgs = [
875	      "docker",
876	      "run",
877	      "--rm",
878	      "--user", `${process.getuid?.() ?? 1000}:${process.getgid?.() ?? 1000}`,
879	      "--cap-drop", "ALL",
880	      "--security-opt", "no-new-privileges",
881	      ...(networkAllowed ? [] : ["--network", "none"]),
882	      "--pids-limit", DOCKER_PIDS_LIMIT,
883	      "--read-only",
884	      "--tmpfs", "/tmp:rw,nosuid,nodev,size=256m",
885	    ];
886	    // Nothing is inherited: the container starts with the scrubbed command environment only. HOME, PATH and TMPDIR
887	    // name host paths, so they are replaced with container paths.
888	    const containerEnv = { ...buildCommandEnvironment(), HOME: "/tmp", PATH: "/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin", TMPDIR: "/tmp" };
889	    for (const [name, value] of Object.entries(containerEnv)) dockerArgs.push("--env", `${name}=${value}`);
890	    dockerArgs.push("-v", `${absWorkspace}:${absWorkspace}`);
891	    // When the workspace is HOME or above it, the bind would bring credential paths back (same hole as bwrap's
892	    // workspace bind, see sandboxWorkspaceOverlays). Docker mounts by destination depth, so these nested mounts sit
893	    // on top of the workspace mount. The docker socket and /run/user cannot lie inside a workspace bind, so they
894	    // need no mask here.
895	    const overlays = sandboxWorkspaceOverlays(absWorkspace);
896	    for (const dir of overlays.dirs) dockerArgs.push("--tmpfs", `${dir}:ro,nosuid,nodev,size=1m`);
897	    for (const file of overlays.files) dockerArgs.push("-v", `/dev/null:${file}:ro`);
898	    dockerArgs.push("-w", absWorkspace, image, "sh", "-c", cmd);
899	
900	    return {
901	      command: dockerArgs.map(quoteForShell).join(" "),
902	      argv: dockerArgs,
903	      sandboxed: true,
904	      engine: "docker",
905	    };
906	  }
907	
908	  return {
909	    command: cmd,
910	    sandboxed: false,
911	    engine: "none",
912	    warning: "No sandboxing engine (bwrap or docker) available. Running directly on host.",
913	  };
