94	/** The directories under HOME a write-mode sandbox binds back read-only. Pure function of HOME, PATH and the operator setting. */
95	export function sandboxHomeMounts(env: NodeJS.ProcessEnv = process.env): SandboxHomeMounts {
96	  const home = path.resolve(env.HOME || os.homedir());
97	  const result: SandboxHomeMounts = { home, mounts: [], masked: [], refused: [] };
98	  if (home === "/") return result;
99	  const seen = new Set<string>();
100	  const consider = (raw: string, source: SandboxHomeMount["source"]): void => {
101	    const candidate = path.resolve(raw.startsWith("~/") ? path.join(home, raw.slice(2)) : raw);
102	    if (!isPathWithin(candidate, home) || candidate === home || seen.has(candidate)) return;
103	    seen.add(candidate);
104	    const refusal = deniedReason(candidate, home);
105	    if (refusal) {
106	      if (source !== "default") result.refused.push({ path: candidate, reason: refusal });
107	      return;
108	    }
109	    let real: string;
110	    try {
111	      real = fs.realpathSync(candidate);
112	      if (!fs.statSync(real).isDirectory()) return;
113	    } catch {
114	      return;
115	    }
116	    // A symlink must not lead into a credential directory.
117	    const realHome = (() => { try { return fs.realpathSync(home); } catch { return home; } })();
118	    if (isPathWithin(real, realHome)) {
119	      const viaLink = deniedReason(real, realHome);
120	      if (viaLink) {
121	        result.refused.push({ path: candidate, reason: `resolves to a path ${viaLink}` });
122	        return;
123	      }
124	    }
125	    result.mounts.push({ path: candidate, source });
126	  };
127	  for (const entry of HOME_TOOLCHAIN_DEFAULTS) consider(path.join(home, entry), "default");
128	  for (const dir of (env.PATH || "").split(path.delimiter).filter(Boolean)) {
129	    const resolved = path.resolve(dir);
130	    if (!isPathWithin(resolved, home)) continue;
131	    // `<prefix>/bin` needs its prefix for lib/ (npm, node_modules); prefix must itself be a safe directory.
132	    const prefix = path.basename(resolved) === "bin" ? path.dirname(resolved) : resolved;
133	    if (prefix !== resolved && prefix !== home && !deniedReason(prefix, home)) consider(prefix, "PATH");
134	    else consider(resolved, "PATH");
135	  }
136	  for (const raw of (operatorSetting(SANDBOX_HOME_READONLY_SETTING) ?? "").split(",").map((v) => v.trim()).filter(Boolean)) {
137	    consider(raw, "operator");
138	  }
139	  // Drop mounts nested inside another mount (the outer one already provides them).
140	  result.mounts = result.mounts.filter((m) => !result.mounts.some((o) => o !== m && o.path !== m.path && isPathWithin(m.path, o.path)));
141	  for (const rel of HOME_MASKED_FILES) {
142	    const file = path.join(home, rel);
143	    if (result.mounts.some((m) => isPathWithin(file, m.path)) && fs.existsSync(file)) result.masked.push(file);
144	  }
145	  return result;
146	}
