153	/**
154	 * The writable workspace bind is applied on top of the masked HOME, so when the workspace is HOME, sits above it, or
155	 * contains a credential directory, it would bring that directory back. These are the existing credential paths
156	 * (the specific HOME_DENIED entries and the masked files) that lie inside the workspace: a directory gets an empty
157	 * tmpfs and a file /dev/null mounted over it, after the workspace bind. Pure function of HOME, the workspace and the
158	 * file system.
159	 */
160	export function sandboxWorkspaceOverlays(workspace: string, env: NodeJS.ProcessEnv = process.env): SandboxWorkspaceOverlays {
161	  const home = path.resolve(env.HOME || os.homedir());
162	  const root = path.resolve(workspace);
163	  const out: SandboxWorkspaceOverlays = { dirs: [], files: [] };
164	  if (home === "/") return out;
165	  const candidates = [...HOME_DENIED.filter((entry) => !BROAD_DENIED.has(entry)), ...HOME_MASKED_FILES].map((rel) => path.join(home, rel));
166	  for (const candidate of candidates) {
167	    if (!isPathWithin(candidate, root)) continue;
168	    // A symlink is overlaid at its target when that lies inside the workspace; the link then reads the overlay.
169	    let target = candidate;
170	    try {
171	      if (fs.lstatSync(candidate).isSymbolicLink()) target = fs.realpathSync(candidate);
172	    } catch {
173	      continue;
174	    }
175	    if (!isPathWithin(target, root)) continue;
176	    try {
177	      const stat = fs.statSync(target);
178	      const list = stat.isDirectory() ? out.dirs : stat.isFile() ? out.files : undefined;
179	      if (list && !list.includes(target)) list.push(target);
180	    } catch {
181	      // Dangling link or vanished path: nothing to hide.
182	    }
183	  }
184	  return out;
185	}
