262	/** Add one trusted runtime file and its dynamic loader dependencies to a synthetic root. */
263	function appendRuntimeFile(
264	  args: string[],
265	  source: string,
266	  knownDirectories: Set<string>,
267	  mountedFiles: Set<string>,
268	  depth = 0,
269	): void {
270	  if (depth > 4) return;
271	  let resolved: string;
272	  try {
273	    resolved = fs.realpathSync(source);
274	    if (!fs.statSync(resolved).isFile() || mountedFiles.has(source)) return;
275	  } catch {
276	    return;
277	  }
278	
279	  appendDirectoryTree(args, path.dirname(source), knownDirectories);
280	  args.push("--ro-bind", resolved, source);
281	  mountedFiles.add(source);
282	
283	  // Runtime commands in the read-only allowlist are fixed platform binaries. Mount their
284	  // individual ELF dependencies, never the containing host directories.
285	  try {
286	    const output = execFileSync("ldd", [resolved], { encoding: "utf8", timeout: 2_000, stdio: ["ignore", "pipe", "ignore"] });
287	    for (const line of output.split("\n")) {
288	      const match = line.match(/(?:=>\s*)?(\/[^\s]+)\s+\(/);
289	      if (match?.[1]) appendRuntimeFile(args, match[1], knownDirectories, mountedFiles, depth + 1);
290	    }
291	  } catch {
292	    // Static binaries and scripts do not have ldd dependencies.
293	  }
294	
295	  // The only runtime script admitted here is an installed command with a fixed shebang.
296	  let fd: number | undefined;
297	  try {
298	    fd = fs.openSync(resolved, "r");
299	    const prefix = Buffer.alloc(256);
300	    const count = fs.readSync(fd, prefix, 0, prefix.length, 0);
301	    const firstLine = prefix.subarray(0, count).toString("utf8").split("\n", 1)[0];
302	    const shebang = firstLine.match(/^#!\s*(\/[^\s]+)/)?.[1];
303	    if (shebang) appendRuntimeFile(args, shebang, knownDirectories, mountedFiles, depth + 1);
304	  } catch {
305	    // Binary files are not UTF-8 scripts.
306	  } finally {
307	    if (fd !== undefined) fs.closeSync(fd);
308	  }
309	}
