463	/** Resolve only root-owned system inspection tools; PATH may contain workspace-controlled entries. */
464	function trustedSystemTool(name: string): string | undefined {
465	  for (const directory of ["/usr/bin", "/bin", "/usr/sbin", "/sbin"]) {
466	    const candidate = path.join(directory, name);
467	    try {
468	      const stat = fs.statSync(candidate);
469	      if (!stat.isFile() || stat.uid !== 0 || (stat.mode & 0o022) !== 0) continue;
470	      fs.accessSync(candidate, fs.constants.X_OK);
471	      return fs.realpathSync(candidate);
472	    } catch {
473	      // Try the next standard system directory.
474	    }
475	  }
476	  return undefined;
