479	function readElfRuntimeInfo(readelf: string, file: string): ElfRuntimeInfo | { error: string } {
480	  let output: string;
481	  try {
482	    output = execFileSync(readelf, ["-hW", "-lW", "-dW", file], {
483	      encoding: "utf8",
484	      timeout: 5_000,
485	      stdio: ["ignore", "pipe", "pipe"],
486	      env: { LC_ALL: "C", PATH: "/usr/bin:/bin:/usr/sbin:/sbin" },
487	    });
488	  } catch (err: any) {
489	    const detail = String(err?.stderr ?? err?.message ?? err).split("\n")[0];
490	    return { error: `ELF metadata could not be read for ${file}: ${detail}` };
491	  }
492	  if (/Not an ELF file|Failed to read file header/i.test(output)) return { error: `${file} is not a readable ELF file.` };
493	  const machine = output.match(/^\s*Machine:\s*(.+)$/m)?.[1].trim();
494	  if (!machine) return { error: `the ELF machine type could not be read for ${file}.` };
495	  const interpreter = output.match(/\[Requesting program interpreter:\s*([^\]]+)\]/)?.[1];
496	  const needed = [...output.matchAll(/\(NEEDED\).*?Shared library:\s*\[([^\]]+)\]/g)].map((match) => match[1]);
497	  const soname = output.match(/\(SONAME\).*?Library soname:\s*\[([^\]]+)\]/)?.[1];
498	  const rawSearchPaths = [...output.matchAll(/\((?:RPATH|RUNPATH)\).*?\[([^\]]*)\]/g)].flatMap((match) => match[1].split(":"));
499	  const origin = path.dirname(file);
500	  const searchPaths = rawSearchPaths.flatMap((entry) => {
501	    const expanded = entry.replace(/\$\{ORIGIN\}|\$ORIGIN/g, origin);
502	    if (!expanded || expanded.includes("$") || !path.isAbsolute(expanded)) return [];
503	    return [expanded];
504	  });
505	  return { interpreter, machine, needed, soname, searchPaths };
506	}
