      if (err instanceof VerifyInterrupted) return fail("interrupted", "interrupted: no verdict was reached");
      throw err;
    } finally {
      process.removeListener("SIGINT", onSignal);
      process.removeListener("SIGTERM", onSignal);
    }
  });

