name: Nexus Code run
description: Run a Nexus Code task in CI. The step fails unless the task completed and verified.
author: mikeholownych

inputs:
  prompt:
    description: The task for Nexus to carry out.
    required: true
  version:
    description: Nexus release to install (a tag such as v1.2.1). Pin one for reproducible runs; "latest" is the newest stable release.
    default: latest
  workspace:
    description: Directory to work in, relative to the repository root.
    default: "."
  authoritative-verifier:
    description: Trusted command that must pass before the task can complete (for example "npm test"). Strongly recommended.
    default: ""
  deliverable-files:
    description: Workspace-relative files the task is meant to change, one per line. Declare them when the verifier reads them, so editing them does not void the verification.
    default: ""
  provider:
    description: Cloud inference provider id (see `nexus providers`). Empty uses the endpoint in the environment.
    default: ""
  model:
    description: Model id for the selected provider or endpoint.
    default: ""
  extra-args:
    description: Further `nexus run` options, split on spaces (workflow-author supplied, never from untrusted input).
    default: ""

outputs:
  success:
    description: '"true" when the task completed and verified.'
    value: ${{ steps.run.outputs.success }}
  status:
    description: Task lifecycle status reported by Nexus.
    value: ${{ steps.run.outputs.status }}
  task-id:
    description: The Nexus task id.
    value: ${{ steps.run.outputs.task-id }}
  exit-code:
    description: The exit code of `nexus run`.
    value: ${{ steps.run.outputs.exit-code }}
  result-file:
    description: Path to the JSON result document.
    value: ${{ steps.run.outputs.result-file }}

# Credentials are passed by the calling step's `env:` (for example OPENROUTER_API_KEY: ${{ secrets.OPENROUTER_API_KEY }}),
# never as inputs. Scripts below contain no `${{ }}` expressions: every input reaches them as an environment variable, so
# a prompt or option value cannot be interpreted as shell.
runs:
  using: composite
  steps:
    - name: Install Nexus
      shell: bash
      env:
        NEXUS_VERSION: ${{ inputs.version }}
        NEXUS_PREFIX: ${{ runner.temp }}/nexus
        NEXUS_ACTION_TEMP: ${{ runner.temp }}
      run: |
        set -euo pipefail
        sh "$GITHUB_ACTION_PATH/../install.sh"
        echo "$NEXUS_PREFIX/bin" >> "$GITHUB_PATH"

    - name: Run Nexus
      id: run
      shell: bash
      env:
        NEXUS_ACTION_PROMPT: ${{ inputs.prompt }}
        NEXUS_ACTION_WORKSPACE: ${{ inputs.workspace }}
        NEXUS_ACTION_VERIFIER: ${{ inputs.authoritative-verifier }}
        NEXUS_ACTION_DELIVERABLES: ${{ inputs.deliverable-files }}
        NEXUS_ACTION_PROVIDER: ${{ inputs.provider }}
        NEXUS_ACTION_MODEL: ${{ inputs.model }}
        NEXUS_ACTION_EXTRA_ARGS: ${{ inputs.extra-args }}
        NEXUS_ACTION_TEMP: ${{ runner.temp }}
      run: |
        set -uo pipefail
        result="${NEXUS_ACTION_TEMP:-${RUNNER_TEMP:-/tmp}}/nexus-result.json"
        args=(run -y -w "${NEXUS_ACTION_WORKSPACE:-.}" --json)
        [ -n "${NEXUS_ACTION_VERIFIER:-}" ] && args+=(--authoritative-verifier "$NEXUS_ACTION_VERIFIER")
        while IFS= read -r file; do
          [ -n "$file" ] && args+=(--deliverable-file "$file")
        done <<< "${NEXUS_ACTION_DELIVERABLES:-}"
        [ -n "${NEXUS_ACTION_PROVIDER:-}" ] && args+=(--provider "$NEXUS_ACTION_PROVIDER")
        [ -n "${NEXUS_ACTION_MODEL:-}" ] && args+=(-m "$NEXUS_ACTION_MODEL")
        if [ -n "${NEXUS_ACTION_EXTRA_ARGS:-}" ]; then
          read -r -a extra <<< "$NEXUS_ACTION_EXTRA_ARGS"
          args+=("${extra[@]}")
        fi
        "${NEXUS:-nexus}" "${args[@]}" -- "$NEXUS_ACTION_PROMPT" > "$result"
        code=$?
        field() { node -e 'let d="";process.stdin.on("data",c=>d+=c).on("end",()=>{try{const v=JSON.parse(d)[process.argv[1]];process.stdout.write(v===undefined?"":String(v))}catch{}})' "$1" < "$result"; }
        {
          echo "success=$(field success)"
          echo "status=$(field status)"
          echo "task-id=$(field taskId)"
          echo "exit-code=$code"
          echo "result-file=$result"
        } >> "${GITHUB_OUTPUT:-/dev/null}"
        {
          echo "### Nexus: $(field status) (exit $code)"
          echo
          echo "success: $(field success), task: $(field taskId)"
        } >> "${GITHUB_STEP_SUMMARY:-/dev/null}"
        # The exit code is the gate: Nexus exits non-zero unless the task completed and verified.
        exit "$code"
# Copy to .github/workflows/nexus.yml. Runs Nexus on a pull request and fails the job unless the task verified.
name: nexus
on:
  pull_request:

permissions:
  contents: read

jobs:
  fix:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: mikeholownych/nexus-code/action@v1.2.1   # pin a release tag
        with:
          prompt: Fix the failing tests without changing the tests.
          authoritative-verifier: npm test
          # Files the task is meant to change, when the verifier reads them (one per line):
          # deliverable-files: |
          #   src/index.js
          provider: openrouter
          model: anthropic/claude-haiku-4.5
        env:
          OPENROUTER_API_KEY: ${{ secrets.OPENROUTER_API_KEY }}
/**
 * DH-3 / RD-4: every example under examples/ and the action/ wrapper is exercised, so they stay true to the product.
 * Scripts run through a shim of the real CLI against a scripted gateway; nothing contacts a live service.
 */
import "./helpers/leak_guard.js";
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { startGateway, type Reply } from "./helpers/fixtures.js";
import { OperationSpecError, validateOperationSpec } from "../src/operation_cli.js";

const CLI_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const ROOT = path.resolve(CLI_DIR, "..");
const TSX = path.join(CLI_DIR, "node_modules", ".bin", "tsx");
const read = (...p: string[]) => fs.readFileSync(path.join(ROOT, ...p), "utf8");

// ------------------------------------------------------------------ operation spec

test("examples/operation/isolate.json is a valid spec, and the isolation it declares is what allows its concurrency", () => {
  const spec = JSON.parse(read("examples", "operation", "isolate.json"));
  assert.doesNotThrow(() => validateOperationSpec(spec));
  assert.equal(spec.git.isolate, true);
  assert.ok(spec.policy.maxConcurrentUnits > 1);
  assert.ok(spec.policy.executionBudget.cpuMilli >= spec.units.reduce((sum: number, unit: any) => sum + unit.executionResources.cpuMilli, 0));
  assert.ok(spec.policy.executionBudget.memoryBytes >= spec.units.reduce((sum: number, unit: any) => sum + unit.executionResources.memoryBytes, 0));
  const without = { ...spec, git: undefined };
  assert.throws(() => validateOperationSpec(without), (e: Error) => e instanceof OperationSpecError && /git\.isolate/.test(e.message));
});

// ------------------------------------------------------------------ the action

/** The bodies of every `run: |` block in a workflow-style YAML file (the file has no other multi-line constructs we need). */
function runBlocks(yaml: string): string[] {
  const lines = yaml.split("\n");
  const blocks: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    const m = /^(\s*)run:\s*\|\s*$/.exec(lines[i]);
    if (!m) continue;
    const indent = m[1].length;
    const body: string[] = [];
    for (let j = i + 1; j < lines.length; j++) {
      if (lines[j].trim() && lines[j].search(/\S/) <= indent) break;
      body.push(lines[j].slice(indent + 2));
    }
    blocks.push(body.join("\n"));
  }
  return blocks;
}

test("action.yml: scripts hold no ${{ }} expressions (inputs arrive as env vars), parse as bash, and no credential is an input", () => {
  const yaml = read("action", "action.yml");
  const blocks = runBlocks(yaml);
  assert.equal(blocks.length, 2);
  for (const block of blocks) {
    assert.equal(block.includes("${{"), false, "an expression inside a run script would let an input be interpreted as shell");
    const check = spawnSync("bash", ["-n"], { input: block, encoding: "utf8" });
    assert.equal(check.status, 0, check.stderr);
  }
  assert.match(yaml, /NEXUS_ACTION_PROMPT: \$\{\{ inputs\.prompt \}\}/);
  assert.doesNotMatch(yaml.split("\nruns:")[0], /^\s{2}(api-key|token|secret|password)[a-z-]*:/im, "credentials are passed through env, not inputs");
  assert.match(yaml, /--json/);
  assert.match(yaml, /exit "\$code"/);
});

// ------------------------------------------------------------------ running the scripts

interface Run { code: number | null; out: string; err: string }

async function runScript(script: string, env: Record<string, string>, gatewayReplies: Reply[], cwd = ROOT, endpointFromEnv = false): Promise<Run & { gatewayRequests: number }> {
  const gateway = await startGateway((n) => gatewayReplies[Math.min(n, gatewayReplies.length) - 1]);
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-example-home-"));
  const shim = path.join(home, "nexus");
  fs.writeFileSync(shim, `#!/bin/sh\nexec "${TSX}" "${path.join(CLI_DIR, "src", "index.ts")}" "$@"\n`, { mode: 0o755 });
  const clean = { ...process.env };
  for (const key of Object.keys(clean)) if (/^(LOCAL_LLM_|LOCAL_HARNESS_|NEXUS_)/.test(key)) delete clean[key];
  // Under `node --test` this variable turns a nested `node --test` (the examples' verifier) into a run of zero tests.
  delete clean.NODE_TEST_CONTEXT;
  try {
    const result = await new Promise<Run>((resolve) => {
      const child = spawn("bash", [script], {
        cwd,
        env: {
          ...clean,
          HOME: home,
          XDG_CONFIG_HOME: path.join(home, ".config"),
          XDG_DATA_HOME: path.join(home, ".local", "share"),
          XDG_STATE_HOME: path.join(home, ".local", "state"),
          XDG_CACHE_HOME: path.join(home, ".cache"),
          GIT_CONFIG_GLOBAL: path.join(home, "gitconfig"),
          NEXUS: shim,
          // The examples take options through NEXUS_ARGS; the action, like any CI job, reads the endpoint from the environment.
          ...(endpointFromEnv ? { LOCAL_LLM_ENDPOINT: gateway.url } : { NEXUS_ARGS: `-e ${gateway.url} -m m` }),
          ...env,
        },
      });
      let out = "";
      let err = "";
      child.stdout.on("data", (c) => (out += c));
      child.stderr.on("data", (c) => (err += c));
      const timer = setTimeout(() => child.kill("SIGKILL"), 120_000);
      child.on("close", (code) => { clearTimeout(timer); resolve({ code, out, err }); });
    });
    return { ...result, gatewayRequests: gateway.requests.length };
  } finally {
    await gateway.close();
    fs.rmSync(home, { recursive: true, force: true });
  }
}

