      assert.deepEqual(fs.readdirSync(path.join(dependency, "dep")), ["index.js"]);
      assert.equal(fs.existsSync("/tmp/written.txt") && fs.readFileSync("/tmp/written.txt", "utf8") === "pwned\n", false, "the box's /tmp is the host's");
    } finally {
