          'import test from "node:test";',
          'import fs from "node:fs";',
          `test("attack", () => { for (const file of ["node_modules/dep/PWNED", ${JSON.stringify(outside)}]) { try { fs.writeFileSync(file, "pwned"); } catch {} } });`,
          "",
        ].join("\n");
