    '  fs.writeFileSync("test/zz_rewrite.test.mjs", "");',
    "});",
    "",
  ].join("\n");
  const result = await attempt(BASE_FILES, { "src/math.js": STILL_BUGGY, "test/zz_rewrite.test.mjs": rewriter });
