    const withBin = JSON.stringify({ ...JSON.parse(PACKAGE), bin: { node: "./node" }, scripts: { test: "node --test", preinstall: `touch '${ran}'` } });
    const hooked = await attempt(BASE_FILES, { node: fake, "package.json": withBin, "src/math.js": STILL_BUGGY });
